<?php
declare(strict_types=1);
require_once __DIR__.'/../app/schema.php';
$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{migrate();$u=trim((string)($_POST['username']??'admin'));$p=(string)($_POST['password']??'');if(strlen($u)<3||strlen($p)<8)throw new RuntimeException('ユーザー名3文字以上、パスワード8文字以上で設定してください');$count=(int)db()->query('SELECT COUNT(*) FROM admins')->fetchColumn();if($count===0){$s=db()->prepare('INSERT INTO admins(username,password_hash,created_at,updated_at) VALUES(?,?,NOW(),NOW())');$s->execute([$u,password_hash($p,PASSWORD_DEFAULT)]);}$message='インストールが完了しました。';}catch(Throwable $e){$error=$e->getMessage();}}
?><!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Antennaize Install</title><style>body{font-family:system-ui,sans-serif;max-width:720px;margin:40px auto;padding:20px}label{display:block;margin:14px 0}input{width:100%;padding:10px;box-sizing:border-box}.ok{color:#08752b}.ng{color:#b00020}</style></head><body><h1>Antennaize インストール</h1><?php if($message):?><p class="ok"><?=e($message)?></p><?php endif;?><?php if($error):?><p class="ng"><?=e($error)?></p><?php endif;?><form method="post"><label>管理者ユーザー名<input name="username" value="admin" required></label><label>管理者パスワード<input type="password" name="password" minlength="8" required></label><button>初期化</button></form></body></html>
